# Manual analysis of changes
inputs = ['gufwdv', 'vz', 'evifi', 'cub', 'cji']
outputs = ['gvfafwdv', 'vz', 'zevefe', 'cvfab', 'cje']

print("Analyzing changes:")
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        print(f"'{inputs[i]}' -> '{outputs[i]}'")
        # Let's examine differences
        in_str, out_str = inputs[i], outputs[i]
        print(f"  Length diff: {len(out_str) - len(in_str)}")
        # Find where they differ
        min_len = min(len(in_str), len(out_str))
        for j in range(min_len):
            if in_str[j] != out_str[j]:
                print(f"  First difference at pos {j}: '{in_str[j]}' -> '{out_str[j]}'")
                break
        else:
            if len(in_str) != len(out_str):
                print(f"  Extension at end: added '{out_str[len(in_str):]}'")
        print()

